   647  bool CodeStreamDecompress::readHeaderProcedureImpl(void)
   648  {
   649     bool has_siz = false;
   650     bool has_cod = false;
   651     bool has_qcd = false;
   652
   653     decompressorState_.setState(DECOMPRESS_STATE_MH_SOC);
   654
   655     /* Try to read the SOC marker, the code stream must begin with SOC marker */
   656     if(!read_soc())
   657     {
   658            Logger::logger_.error("Code stream must begin with SOC marker ");
   659            return false;
   660     }
   661     if(!readMarker())
   662            return false;
   663
   664     if(curr_marker_ != J2K_SIZ)
   665     {
   666            Logger::logger_.error(
   667                    "Code-stream must contain a valid SIZ marker segment, immediately after the SOC "
   668                    "marker ");
   669            return false;
   670     }
   671
   672     /* read until first SOT is detected */
   673     while(curr_marker_ != J2K_SOT)
   674     {
   675            // 1. get handler handler
   676            auto marker_handler = get_marker_handler(curr_marker_);
   677            if(!marker_handler)
   678            {
   679                   if(!read_unk())
   680                          return false;
   681                   if(curr_marker_ == J2K_SOT)
   682                          break;
   683                   marker_handler = get_marker_handler(curr_marker_);
   684            }
   685            if(marker_handler->id == J2K_SIZ)
   686                   has_siz = true;
   687            else if(marker_handler->id == J2K_COD)
   688                   has_cod = true;
   689            else if(marker_handler->id == J2K_QCD)
   690                   has_qcd = true;
   691
   692            /* Check if the marker is known and if it is in the correct location
   693             * (main, tile, end of code stream)*/
   694            if(!(decompressorState_.getState() & marker_handler->states))
   695            {
   696                   Logger::logger_.error("Marker %u is not compliant with its position", curr_marker_);
   697                   return false;
   698            }
   699
   700            // 2. read rest of marker segment
   701            uint16_t markerParametersLength;
   702            if(!read_short(&markerParametersLength))
   703                   return false;
   704            else if(markerParametersLength == MARKER_LENGTH_BYTES)
   705            {
   706                   Logger::logger_.error("Zero-size marker in header.");
   707                   return false;
   708            }
   709            markerParametersLength = (uint16_t)(markerParametersLength - MARKER_LENGTH_BYTES);
   710
   711            // 3. handle marker
   712            if(!process_marker(marker_handler, markerParametersLength))
   713                   return false;
   714
   715            // 4. add the marker to code stream index
   716            uint16_t markerSegmentLength = MARKER_PLUS_MARKER_LENGTH_BYTES + markerParametersLength;
   717            addMarker(marker_handler->id, stream_->tell() - markerSegmentLength, markerSegmentLength);
   718
   719            // 5. read next marker
   720            if(!readMarker())
   721                   return false;
   722     }
   723     if(!has_siz)
   724     {
   725            Logger::logger_.error("required SIZ marker not found in main header");
   726            return false;
   727     }
   728     else if(!has_cod)
   729     {
   730            Logger::logger_.error("required COD marker not found in main header");
   731            return false;
   732     }
   733     else if(!has_qcd)
